using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    [ColumnName("Label")]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedCategory { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];

    /// <summary>Returns category names in the same order as Score array.</summary>
    public string[] CategoryScores() => ["Billing", "General", "Technical"];
}

public record TicketRequest(string Subject, string Description, float Priority);

public record EvaluationMetrics(
    double MicroAccuracy,
    double MacroAccuracy,
    double LogLoss,
    double LogLossReduction);

using Microsoft.ML;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class ModelTrainingService
{
    private readonly MLContext _mlContext;
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly IServiceProvider _services;
    private readonly ILogger<ModelTrainingService> _logger;

    public ModelTrainingService(IServiceProvider services, ILogger<ModelTrainingService> logger)
    {
        _mlContext = new MLContext(seed: 42);
        _dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        _modelPath = Path.Combine(AppContext.BaseDirectory, "ticket_model.zip");
        _services = services;
        _logger = logger;
    }

    public EvaluationMetrics TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.3, seed: 42);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label")
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training ticket classifier model...");
        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation(
            "Model metrics — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

        // Save model and register with PredictionEnginePool
        _mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        // Configure the pool to load from the saved model file
        var poolOptions = _services.GetRequiredService<Microsoft.Extensions.Options.IOptions<PredictionEnginePoolOptions<TicketInput, TicketPrediction>>>();
        poolOptions.Value.ModelLoader = new ModelLoader(_mlContext, _modelPath);

        return new EvaluationMetrics(
            metrics.MicroAccuracy,
            metrics.MacroAccuracy,
            metrics.LogLoss,
            metrics.LogLossReduction);
    }
}

/// <summary>Simple model loader that reads from a file path.</summary>
internal sealed class ModelLoader : Microsoft.Extensions.ML.ModelLoader
{
    private readonly MLContext _mlContext;
    private readonly string _modelPath;
    private ITransformer? _model;

    public ModelLoader(MLContext mlContext, string modelPath)
    {
        _mlContext = mlContext;
        _modelPath = modelPath;
    }

    public override ITransformer GetModel() =>
        _model ??= _mlContext.Model.Load(_modelPath, out _);

    public override void Start() { }

    public override void Stop() { }
}

