using Microsoft.ML;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<ModelTrainingService>();
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>();

var app = builder.Build();

// Train the model at startup and configure the prediction engine pool
var trainingService = app.Services.GetRequiredService<ModelTrainingService>();
var metrics = trainingService.TrainAndEvaluate();

app.MapGet("/", () => "Ticket Classifier API - POST to /predict or GET /metrics");

app.MapGet("/metrics", () => metrics);

app.MapPost("/predict", (TicketRequest request, PredictionEnginePool<TicketInput, TicketPrediction> pool) =>
{
    var input = new TicketInput
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority
    };

    var prediction = pool.Predict(input);

    return Results.Ok(new
    {
        PredictedCategory = prediction.PredictedCategory,
        Confidence = prediction.Score.Zip(prediction.CategoryScores(), (s, c) => new { Category = c, Score = s })
    });
});

app.Run();

